begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
set local session_replication_role=replica;
insert into auth.users(id,email) values ('ab177800-0000-4000-8000-000000000001','transition-admin@example.invalid'),('ab177800-0000-4000-8000-000000000002','transition-outsider@example.invalid');
insert into public.admin_roles(user_id,role,active) values('ab177800-0000-4000-8000-000000000001','super_admin',true);
insert into public.customer_accounts(id,name) values('ab177801-0000-4000-8000-000000000001','Synthetic transition company');
insert into public.reporting_locations(id,account_id,name,timezone) values('ab177802-0000-4000-8000-000000000001','ab177801-0000-4000-8000-000000000001','Synthetic internal venue','America/Chicago');
insert into public.reporting_machines(id,account_id,location_id,machine_label,machine_type,nayax_manual_portal_enabled,nayax_manual_account_scope,nayax_manual_portal_timezone,nayax_refunds_enabled,refund_intake_enabled,sunze_machine_id) values
('ab177803-0000-4000-8000-000000000001','ab177801-0000-4000-8000-000000000001','ab177802-0000-4000-8000-000000000001','Synthetic manual transition','commercial',true,'synthetic_manual','America/Chicago',false,false,'synthetic-sunze-1778'),
('ab177803-0000-4000-8000-000000000002','ab177801-0000-4000-8000-000000000001','ab177802-0000-4000-8000-000000000001','Synthetic untouched manual','commercial',true,'synthetic_manual','America/Chicago',false,false,null);
insert into public.refund_nayax_machine_inventory(id,account_key,nayax_machine_id,machine_name,provider_is_active,reconciliation_state) values('ab177804-0000-4000-8000-000000000001','FIXTURE_1778','17780001','Synthetic exact reader',true,'needs_setup');
insert into public.machine_sales_facts(reporting_machine_id,reporting_location_id,sale_date,payment_method,net_sales_cents,transaction_count,source,source_row_hash) values('ab177803-0000-4000-8000-000000000001','ab177802-0000-4000-8000-000000000001','2026-09-01','cash',1200,2,'manual_csv',repeat('a',64));
insert into public.machine_sales_facts(reporting_machine_id,reporting_location_id,sale_date,payment_method,net_sales_cents,transaction_count,source,source_row_hash,source_order_hash) values('ab177803-0000-4000-8000-000000000001','ab177802-0000-4000-8000-000000000001','2026-09-02','credit',900,3,'sunze_browser',repeat('b',64),repeat('c',64));
insert into public.refund_cases(id,public_reference,reporting_machine_id,reporting_location_id,customer_email,issue_summary,incident_at,payment_method,payment_amount_cents,status,customer_request_received_at,customer_request_received_source) values('ab177805-0000-4000-8000-000000000001','RF-1778-SYNTHETIC','ab177803-0000-4000-8000-000000000001','ab177802-0000-4000-8000-000000000001','transition-case@example.invalid','Synthetic historical evidence','2026-09-01T12:00Z','credit',1200,'needs_review','2026-09-01T12:00Z','hosted_refund_intake');
insert into public.refund_nayax_lookup_candidates(token,refund_case_id,reporting_machine_id,lookup_generation,provider_transaction_id,machine_authorization_time,amount_cents,card_last4,currency_code) values('ab177806-0000-4000-8000-000000000001','ab177805-0000-4000-8000-000000000001','ab177803-0000-4000-8000-000000000001',1,'FIXTURE-MANUAL-1778','2026-09-01T12:00Z',1200,'4242','USD');
insert into public.refund_manual_nayax_evidence(refund_case_id,reporting_machine_id,actor_user_id,account_scope,portal_machine_reference,provider_transaction_id,machine_authorization_time,amount_cents,card_last4,candidate_token) values('ab177805-0000-4000-8000-000000000001','ab177803-0000-4000-8000-000000000001','ab177800-0000-4000-8000-000000000001','synthetic_manual','Synthetic portal machine','FIXTURE-MANUAL-1778','2026-09-01T12:00Z',1200,'4242','ab177806-0000-4000-8000-000000000001');
-- Settle synthetic source authority exactly as normal imports do before snapshot.
set local session_replication_role=origin;
select private.reconcile_machine_card_sales_authority('ab177803-0000-4000-8000-000000000001','2026-09-02'::date);
create temporary table original_machine as select to_jsonb(m) value from reporting_machines m where id='ab177803-0000-4000-8000-000000000001';
create temporary table original_history as select jsonb_build_object('facts',(select jsonb_agg(to_jsonb(f)) from machine_sales_facts f where reporting_machine_id='ab177803-0000-4000-8000-000000000001'),'candidates',(select jsonb_agg(to_jsonb(c)) from refund_nayax_lookup_candidates c where reporting_machine_id='ab177803-0000-4000-8000-000000000001'),'cases',(select jsonb_agg(to_jsonb(c)) from refund_cases c where reporting_machine_id='ab177803-0000-4000-8000-000000000001'),'evidence',(select jsonb_agg(to_jsonb(e)) from refund_manual_nayax_evidence e where reporting_machine_id='ab177803-0000-4000-8000-000000000001')) value;
set local session_replication_role=origin;
select set_config('request.jwt.claim.role','authenticated',true);
select set_config('request.jwt.claim.sub','ab177800-0000-4000-8000-000000000001',true);
select throws_ok($$update reporting_machines set nayax_machine_id='17780001',nayax_account_key='FIXTURE_1778' where id='ab177803-0000-4000-8000-000000000001'$$,'23514',null,'Raw mixed manual/API UPDATE remains forbidden by unchanged constraints');
select lives_ok($$select admin_set_reporting_machine_nayax_config('ab177803-0000-4000-8000-000000000002',null,null,'Synthetic preserve manual')$$,'Null reader preserves valid manual configuration');
select ok((select nayax_manual_portal_enabled and nayax_manual_account_scope='synthetic_manual' and nayax_manual_portal_timezone='America/Chicago' from reporting_machines where id='ab177803-0000-4000-8000-000000000002'),'No-reader save retains all manual fields');
select lives_ok($$select admin_save_machine_workspace_mapping('ab177803-0000-4000-8000-000000000001',null,'ab177804-0000-4000-8000-000000000001',null,null,null)$$,'Exact imported reader assignment atomically transitions manual mode');
select ok((select not nayax_manual_portal_enabled and nayax_manual_account_scope is null and nayax_manual_portal_timezone is null and nayax_machine_id='17780001' and nayax_account_key='FIXTURE_1778' from reporting_machines where id='ab177803-0000-4000-8000-000000000001'),'All manual exclusivity fields clear with exact API tuple');
select is((select to_jsonb(m)-array['updated_at','nayax_machine_id','nayax_account_key','nayax_manual_portal_enabled','nayax_manual_account_scope','nayax_manual_portal_timezone'] from reporting_machines m where id='ab177803-0000-4000-8000-000000000001'),(select value-array['updated_at','nayax_machine_id','nayax_account_key','nayax_manual_portal_enabled','nayax_manual_account_scope','nayax_manual_portal_timezone'] from original_machine),'Capabilities, internal association, names and accounting boundary unchanged');
select is((select reconciliation_state from refund_nayax_machine_inventory where id='ab177804-0000-4000-8000-000000000001'),'needs_setup','Assignment does not publish or enable refunds');
select ok(exists(select 1 from admin_audit_log where entity_id='ab177803-0000-4000-8000-000000000001' and action='reporting_machine.nayax_config.set' and before->>'manual_portal_enabled'='true' and after->>'manual_portal_enabled'='false'),'Canonical audit records manual-to-API transition');
select is(jsonb_build_object('facts',(select jsonb_agg(to_jsonb(f)) from machine_sales_facts f where reporting_machine_id='ab177803-0000-4000-8000-000000000001'),'candidates',(select jsonb_agg(to_jsonb(c)) from refund_nayax_lookup_candidates c where reporting_machine_id='ab177803-0000-4000-8000-000000000001'),'cases',(select jsonb_agg(to_jsonb(c)) from refund_cases c where reporting_machine_id='ab177803-0000-4000-8000-000000000001'),'evidence',(select jsonb_agg(to_jsonb(e)) from refund_manual_nayax_evidence e where reporting_machine_id='ab177803-0000-4000-8000-000000000001')),(select value from original_history),'Financial facts, existing case and manual evidence remain byte-equivalent');
select throws_ok($$select admin_save_machine_workspace_mapping('ab177803-0000-4000-8000-000000000002',null,'ab177804-0000-4000-8000-000000000001',null,null,null)$$,'23505',null,'Occupied reader cannot transition another manual machine');
select ok((select nayax_manual_portal_enabled and nayax_machine_id is null from reporting_machines where id='ab177803-0000-4000-8000-000000000002'),'Failed occupied assignment rolls back manual mode');
select throws_ok($$select admin_save_machine_workspace_mapping('ab177803-0000-4000-8000-000000000001',null,'ab177804-0000-4000-8000-000000000001',null,null,null)$$,'40001',null,'Stale mapping still rejected');
-- Fail after canonical transition/reconciliation to prove complete transaction rollback.
insert into refund_nayax_machine_inventory(id,account_key,nayax_machine_id,machine_name,provider_is_active,reconciliation_state) values('ab177804-0000-4000-8000-000000000002','FIXTURE_1778','17780002','Synthetic rollback reader',true,'needs_setup');
create temporary table rollback_snapshot as select (select to_jsonb(m) from reporting_machines m where id='ab177803-0000-4000-8000-000000000002') machine,(select to_jsonb(i) from refund_nayax_machine_inventory i where id='ab177804-0000-4000-8000-000000000002') inventory,(select count(*) from admin_audit_log) audits;
create function pg_temp.reject_transition_workspace_audit() returns trigger language plpgsql as $$begin if new.action='reporting_machine.workspace_mapping_saved' and new.entity_id='ab177803-0000-4000-8000-000000000002' then raise exception 'Synthetic final audit failure'; end if; return new; end;$$;
create trigger synthetic_1778_audit_failure before insert on admin_audit_log for each row execute function pg_temp.reject_transition_workspace_audit();
select throws_ok($$select admin_save_machine_workspace_mapping('ab177803-0000-4000-8000-000000000002',null,'ab177804-0000-4000-8000-000000000002',null,null,null)$$,'P0001','Synthetic final audit failure','Late failure rolls back successful canonical transition');
select is((select to_jsonb(m) from reporting_machines m where id='ab177803-0000-4000-8000-000000000002'),(select machine from rollback_snapshot),'Late failure preserves complete original manual machine row');
select is((select to_jsonb(i) from refund_nayax_machine_inventory i where id='ab177804-0000-4000-8000-000000000002'),(select inventory from rollback_snapshot),'Late failure preserves complete imported inventory row');
select is((select count(*) from admin_audit_log),(select audits from rollback_snapshot),'Late failure rolls back all canonical/reconciliation audit entries');
drop trigger synthetic_1778_audit_failure on admin_audit_log;
select set_config('request.jwt.claim.sub','ab177800-0000-4000-8000-000000000002',true);
select throws_ok($$select admin_save_machine_workspace_mapping('ab177803-0000-4000-8000-000000000002',null,'ab177804-0000-4000-8000-000000000001',null,null,null)$$,'42501',null,'Unauthorized caller cannot transition mapping');
select ok(not has_function_privilege('anon','public.admin_set_reporting_machine_nayax_config(uuid,text,text,text)','execute'),'Canonical writer retains no anonymous execution');
select * from finish();
rollback;
